// Pega settings e categorias e monta contexto consolidado para o agente
const phone = $('Trigger').first().json.user_phone;

// Settings
const settingsItems = $('GET user_settings').all();
const s = settingsItems.length > 0 ? settingsItems[0].json : {};

const settings = {
  time_manha:    s.time_manha    || '11:00',
  time_tarde:    s.time_tarde    || '17:00',
  time_noite:    s.time_noite    || '20:30',
  time_dia:      s.time_dia      || '15:00',
  report_period: s.report_period || 'noite',
  report_time:   s.report_time   || '21:00',
  timezone:      s.timezone      || 'America/Sao_Paulo'
};

// Categorias
const categories = $('GET categories').all()
  .map(i => ({ id: i.json.id, name: i.json.name, is_default: i.json.is_default }))
  .sort((a, b) => a.name.localeCompare(b.name));

const category_names = categories.map(c => c.name);

return [{ json: {
  user_phone: phone,
  settings,
  categories,
  category_names,
  // Resumo pronto para incluir no contexto do agente
  context_summary: `Configurações do usuário:\n- Manhã: ${settings.time_manha} | Tarde: ${settings.time_tarde} | Noite: ${settings.time_noite} | Dia: ${settings.time_dia}\n- Relatório: ${settings.report_period} às ${settings.report_time}\nCategorias disponíveis: ${category_names.join(', ')}`
}}];
